    private int AtMost(int[] nums, int k) {

        int len = nums.Length;
        int count = 0;
        int left = 0, right = 0;

        Dictionary<int, int> map = new Dictionary<int, int>();

        while(right < len) {

            map[nums[right]] = map.GetValueOrDefault(nums[right], 0) + 1;

            while(map.Keys.Count > k) {
                map[nums[left]]--;
                if(map[nums[left]] == 0) map.Remove(nums[left]);
                left++;
            }

            // count the number of sub arrays from left to right
            count += right - left + 1;
            right++;
        }

        return count;

    }
